import{_ as o,o as t,c,a2 as s}from"./chunks/framework.D7WGirly.js";const k=JSON.parse('{"title":"Session locking","description":"","frontmatter":{},"headers":[],"relativePath":"session-lock.md","filePath":"session-lock.md"}'),r={name:"session-lock.md"};function n(d,e,a,i,l,h){return t(),c("div",null,[...e[0]||(e[0]=[s('<h1 id="session-locking" tabindex="-1">Session locking <a class="header-anchor" href="#session-locking" aria-label="Permalink to &quot;Session locking&quot;">​</a></h1><p>Gnoblin uses the standard <code>ext-session-lock-v1</code> Wayland protocol in the Gnoblin session. The compositor owns the security boundary: it covers every output, stops normal input, replaces desktop capture with its lock scene, and stays locked if a locker exits. The locker owns its appearance and authentication. See the <a href="https://github.com/kierandrewett/gnoblin/blob/main/src/protocols/session-lock/ext-session-lock-v1.xml" target="_blank" rel="noreferrer">protocol XML</a>.</p><p>Gnoblin does not provide a default lock screen. Bingux is one separate shell project with its own lock client.</p><p>Third-party lockers such as hyprlock, swaylock, gtklock and waylock can connect directly to the same standard protocol. Any client with access to this user&#39;s Wayland socket can request the lock; Gnoblin does not filter requests by process. The first request owns the lock, and concurrent requests receive <code>finished</code>.</p><p>In Bingux, use its Lock action or run <code>bingux-lock</code>. With another locker installed, run its command (for example, <code>hyprlock</code>) in your Gnoblin session. Your shell or idle daemon decides when to run that command; Gnoblin does not set a timeout or launch a locker for you.</p><p>The regular GNOME session is separate. It does not advertise this protocol and continues to use GNOME ScreenShield.</p><p>The protocol is enabled by default in Gnoblin. To hide its global, set <code>ext_session_lock = false</code> under <code>gnoblin.configure.protocols</code>, then log out and back in; protocol globals are registered at compositor startup. See the <a href="/config/configure/protocols">protocol setting reference</a>.</p><h2 id="portal-and-remote-access-while-locked" tabindex="-1">Portal and remote access while locked <a class="header-anchor" href="#portal-and-remote-access-while-locked" aria-label="Permalink to &quot;Portal and remote access while locked&quot;">​</a></h2><p>Existing portal permission remains in force. A monitor stream already authorised through the desktop portal receives the compositor lock scene while the session is locked, rather than normal desktop content.</p><p>Remote keyboard and pointer input is available after <code>locked</code> and lock-scene presentation, and is routed only to the active lock surface. It is refused during the transition and failsafe states. This requires no lock-specific portal setting, opt-in, or change to an existing authorised grant.</p><h2 id="locker-requirements" tabindex="-1">Locker requirements <a class="header-anchor" href="#locker-requirements" aria-label="Permalink to &quot;Locker requirements&quot;">​</a></h2><p>A locker binds <code>ext_session_lock_manager_v1</code> and sends <code>lock</code>. The compositor then sends <code>locked</code> or <code>finished</code> on the new lock object. <code>finished</code> means the request was not granted; do not show an authentication UI for that lock.</p><p>After requesting the lock, create one <code>wl_surface</code> per output and pass each to <code>get_lock_surface</code> before attaching or committing a buffer. An output can have only one lock surface for this lock. For every <code>configure(serial, width, height)</code>, acknowledge its serial before committing a non-null buffer with those exact surface-local dimensions. If multiple configures arrive before a commit, acknowledging the latest one is sufficient.</p><table tabindex="0"><thead><tr><th>Interface</th><th>Request or event</th><th>Contract</th></tr></thead><tbody><tr><td><code>ext_session_lock_manager_v1</code></td><td><code>destroy</code></td><td>Release the manager object; existing lock objects remain valid.</td></tr><tr><td><code>ext_session_lock_manager_v1</code></td><td><code>lock</code></td><td>Create a lock request; it later receives <code>locked</code> or <code>finished</code>.</td></tr><tr><td><code>ext_session_lock_v1</code></td><td><code>destroy</code></td><td>Cancel or retire a lock only before <code>locked</code>; destroy its lock surfaces too.</td></tr><tr><td><code>ext_session_lock_v1</code></td><td><code>get_lock_surface(surface, output)</code></td><td>Create the output&#39;s lock surface before the <code>wl_surface</code> has a role or buffer.</td></tr><tr><td><code>ext_session_lock_v1</code></td><td><code>locked</code></td><td>The lock scene has been presented and it is safe to treat the session as locked.</td></tr><tr><td><code>ext_session_lock_v1</code></td><td><code>finished</code></td><td>The compositor did not grant this lock request.</td></tr><tr><td><code>ext_session_lock_v1</code></td><td><code>unlock_and_destroy</code></td><td>After authentication succeeds and <code>locked</code> was received, release the session lock.</td></tr><tr><td><code>ext_session_lock_surface_v1</code></td><td><code>ack_configure(serial)</code></td><td>Acknowledge a configure before committing its buffer.</td></tr><tr><td><code>ext_session_lock_surface_v1</code></td><td><code>configure(serial, width, height)</code></td><td>Resize to the exact output-local dimensions, acknowledge <code>serial</code>, then commit a matching buffer.</td></tr><tr><td><code>ext_session_lock_surface_v1</code></td><td><code>destroy</code></td><td>Retire the lock surface. Removing one for an active output before unlock makes Gnoblin show a solid color there.</td></tr></tbody></table><p>After <code>locked</code>, only the owner calls <code>unlock_and_destroy</code>; destroying the lock object instead is a protocol error. If the client exits immediately after unlocking, send <code>wl_display.sync</code> and wait for its callback before disconnecting so the compositor processes the request. A locker crash leaves the compositor covered and locked; another client may acquire the lock afterwards.</p><p>The protocol rejects a null lock-surface buffer, a commit before the first configure is acknowledged, a buffer with the wrong dimensions, duplicate output surfaces, and destroying the active lock without unlocking. See the <a href="https://github.com/kierandrewett/gnoblin/blob/main/src/protocols/session-lock/ext-session-lock-v1.xml" target="_blank" rel="noreferrer">protocol XML</a> for the complete error enums.</p>',16)])])}const p=o(r,[["render",n]]);export{k as __pageData,p as default};
